func test_clickhouse_TestClickhouse_test_timestr_to_time(self *Case, a Args) Value {
	var time_strings, time_string, time_strings_no_utc, utc, no_utc Value
	_ = []Value{time_strings, time_string, time_strings_no_utc, utc, no_utc}
	self.Do(2028, func() {
		time_strings = NewList("2020-01-01 00:00:01", "2020-01-01 00:00:01+01:00", " 2020-01-01 00:00:01-01:00 ", "2020-01-01T00:00:01+01:00")
	})
	for _, item_ := range Iter(time_strings) {
		time_string = item_
		self.SubTest(func() {
			self.Do(2036, func() {
				self.AssertEqual(M(M(G("sqlglot.exp"), "TimeStrToTime", Kw("this", M(A(G("sqlglot.exp"), "Literal"), "string", time_string))), "sql", Kw("dialect", self.Dialect())), F("CAST('", FV{V: time_string}, "' AS DateTime64(6))"))
			})
		}, F("'", FV{V: time_string}, "'"))
	}
	self.Do(2043, func() {
		time_strings_no_utc = func() Value {
			var i Value
			_ = []Value{i}
			var out []Value
			for _, item_ := range Iter(Call(G("range"), 4)) {
				i = item_
				out = append(out, "2020-01-01 00:00:01")
			}
			return &List{V: out}
		}()
	})
	for _, item_ := range Iter(Call(G("zip"), time_strings, time_strings_no_utc)) {
		Unpack(item_, &utc, &no_utc)
		self.SubTest(func() {
			self.Do(2046, func() {
				self.AssertEqual(M(M(G("sqlglot.exp"), "TimeStrToTime", Kw("this", M(A(G("sqlglot.exp"), "Literal"), "string", utc)), Kw("zone", M(A(G("sqlglot.exp"), "Literal"), "string", "UTC"))), "sql", Kw("dialect", self.Dialect())), F("CAST('", FV{V: no_utc}, "' AS DateTime64(6, 'UTC'))"))
			})
		}, F("'", FV{V: time_string}, "' with UTC timezone"))
	}
	self.Do(2054, func() {
		time_strings = NewList("2020-01-01 00:00:01.001", "2020-01-01 00:00:01.000001", "2020-01-01 00:00:01.001+00:00", "2020-01-01 00:00:01.000001-00:00", "2020-01-01 00:00:01.0001", "2020-01-01 00:00:01.1+00:00")
	})
	for _, item_ := range Iter(time_strings) {
		time_string = item_
		self.SubTest(func() {
			self.Do(2065, func() {
				self.AssertEqual(M(M(G("sqlglot.exp"), "TimeStrToTime", Kw("this", M(A(G("sqlglot.exp"), "Literal"), "string", Item(time_string, 0)))), "sql", Kw("dialect", self.Dialect())), F("CAST('", FV{V: Item(time_string, 0)}, "' AS DateTime64(6))"))
			})
		}, F("'", FV{V: time_string}, "'"))
	}
	self.Do(2072, func() {
		time_strings_no_utc = NewList("2020-01-01 00:00:01.001000", "2020-01-01 00:00:01.000001", "2020-01-01 00:00:01.001000", "2020-01-01 00:00:01.000001", "2020-01-01 00:00:01.000100", "2020-01-01 00:00:01.100000")
	})
	for _, item_ := range Iter(Call(G("zip"), time_strings, time_strings_no_utc)) {
		Unpack(item_, &utc, &no_utc)
		self.SubTest(func() {
			self.Do(2083, func() {
				self.AssertEqual(M(M(G("sqlglot.exp"), "TimeStrToTime", Kw("this", M(A(G("sqlglot.exp"), "Literal"), "string", utc)), Kw("zone", M(A(G("sqlglot.exp"), "Literal"), "string", "UTC"))), "sql", Kw("dialect", self.Dialect())), F("CAST('", FV{V: no_utc}, "' AS DateTime64(6, 'UTC'))"))
			})
		}, F("'", FV{V: time_string}, "' with UTC timezone"))
	}
	return nil
}

